@Patch(':id')
update(@Param('id') id: string, @Body() body: any) {
  // BUG: manual coercion scattered in the handler, no validation, no real DTO
  const userId = Number(id);                 // NaN if junk, never rejected
  if (Number.isNaN(userId)) { /* ...nobody checks... */ }
  const isActive = Boolean(body.active);     // Boolean('false') === true — wrong
  const quantity = parseInt(body.quantity);  // string in, untyped
  return this.users.update(userId, { isActive, quantity });
}

model.en:
// dto
export class UpdateUserDto {
  @Transform(({ value }) => value === true || value === 'true') // value-aware boolean
  @IsBoolean()
  active: boolean;

  @Type(() => Number) // explicit per-field coercion
  @IsInt()
  quantity: number;
}

// controller — ParseIntPipe at the param, DTO + ValidationPipe(transform) for the body
@Patch(':id')
update(
  @Param('id', ParseIntPipe) id: number,          // 400s on junk before the handler runs
  @Body() body: UpdateUserDto,                    // a REAL instance, validated + coerced
) {
  return this.users.update(id, { isActive: body.active, quantity: body.quantity });
}
// (ValidationPipe({ transform: true }) is registered globally in main.ts)

Why: ParseIntPipe makes id a number or 400s before the handler — no hand-rolled Number()/NaN check. The body is now a real UpdateUserDto instance (transform: true runs plainToInstance), with @Type(() => Number) coercing quantity and @Transform parsing the boolean by VALUE so 'false' becomes false (not Boolean('false') === true). @IsInt()/@IsBoolean() validate the coercion result. The coercion is now declared once on the DTO, reused everywhere that shape appears, typed, and testable — instead of scattered, untyped statements in the handler.

